if(insult){r.insults++;r.trust-=16;emotion='Ofendido';response=r.insults===1?'Não gostei disso. Podemos conversar, mas com respeito.':r.insults===2?'Você já passou do limite. Vou me afastar.':'Chega. Estou chamando a polícia. Não se aproxime.';if(r.insults===2&&n.id==='davi'){p.health=Math.max(5,p.health-15);response='Não fala assim comigo! A discussão virou um empurrão. É melhor a gente se afastar.';emotion='Irritado';}if(r.insults===2){n.x=clamp(n.x+120,100,2450);n.mood='Assustado';}if(r.insults>=3){p.wanted=Math.min(3,p.wanted+1);p.heat=Date.now()+45000;}}
else if(/desculp|perdao|sinto muito/.test(t)){r.trust+=9;r.insults=Math.max(0,r.insults-1);response='Agradeço por reconhecer. Preciso ver isso nas suas atitudes também, mas podemos recomeçar.';emotion='Aliviado';}
else if(compliment){r.trust+=5;r.affection+=3;response=n.id==='maya'?'Valeu! É bom ser reconhecida pelo que eu faço. Você também curte carros antigos?':n.id==='leo'?'Poxa, obrigado. Esse café tem muito de mim. Senta um pouco, me conta do seu dia.':n.id==='ana'?'Obrigada pelo carinho. Um pouco de gentileza muda o dia de alguém, sabia?':'Isso me dá uma energia boa! Estou trabalhando em umas músicas novas. Quer ouvir a história?';emotion='Feliz';}
