 s.on('join',({name,token})=>{if(players.has(s.id))return;name=String(name||'Visitante').replace(/[<>]/g,'').trim().slice(0,20)||'Visitante';token=String(token||s.id).replace(/[^a-zA-Z0-9-]/g,'').slice(0,80);if(!token)token=s.id;const other=[...players.values()].find(p=>p.token===token);if(other)token+='-'+s.id;const base=saved.players[token]||{};const p={x:1260,y:1010,cash:450,bank:1000,health:100,needs:{food:90,energy:88,social:72,hygiene:92},inventory:{snack:2,water:2,flower:1},wanted:0,heat:0,car:false,remember:true,reputation:0,xp:0,job:null,color:'#f9d784',...base,id:s.id,token,name,dir:'down',talking:false,police:null};players.set(s.id,p);s.emit('welcome',{player:p,npcs:chars,players:[...players.values()].map(publicPlayer),time:worldMinute,aiMode:npcAI.enabled?'provider':'local'});s.broadcast.emit('playerJoined',publicPlayer(p));me(s,p);notice(s,`Bem-vindo a Porto Neon, ${name}. A cidade é sua.`,'success');});
