 s.on('job',kind=>{const p=players.get(s.id);if(!p)return;if(kind==='cancel'){p.job=null;me(s,p);return;}if(p.job)return notice(s,'Conclua ou cancele seu trabalho atual.');const jobs={delivery:{title:'Entrega expressa',x:2020,y:560,reward:140,desc:'Leve a encomenda até o Hotel Atlântico.'},courier:{title:'Correio do bairro',x:670,y:1370,reward:110,desc:'Leve os documentos à Galeria Maré.'},taxi:{title:'Motorista particular',x:2020,y:1420,reward:200,desc:'Leve o passageiro até a orla. Requer veículo.'}};if(!jobs[kind])return;if(kind==='taxi'&&!p.car)return notice(s,'Pegue um veículo na oficina para trabalhar de motorista.');p.job={...jobs[kind],kind};me(s,p);notice(s,'Trabalho aceito. Siga o marcador amarelo.','success');});
