function endChess(id){if(waitChess===id)waitChess=null;const g=chessGames.get(id);if(g){for(const pid of [g.white,g.black]){if(pid!=='bot'){io.to(pid).emit('chessEnded');chessGames.delete(pid)}}}}
function sendChess(g){for(const id of [g.white,g.black])if(id!=='bot')io.to(id).emit('chessState',{board:g.chess.board(),turn:g.chess.turn(),color:id===g.white?'w':'b',check:g.chess.isCheck(),over:g.chess.isGameOver(),mate:g.chess.isCheckmate(),opponent:g.black==='bot'?'Bot local':players.get(id===g.white?g.black:g.white)?.name||'Jogador'})}
