let tick=0;setInterval(()=>{tick++;for(const [id,p]of players){p.needs.food=clamp(p.needs.food-.025,0,100);p.needs.energy=clamp(p.needs.energy-(p.car?.015:.035),0,100);p.needs.social=clamp(p.needs.social-.014,0,100);p.needs.hygiene=clamp(p.needs.hygiene-.015,0,100);if(p.needs.food<10||p.needs.energy<5)p.health=Math.max(1,p.health-.12);if(p.wanted){if(!p.police)p.police={x:clamp(p.x+190,40,2250),y:clamp(p.y+100,40,1750)};const dx=p.x-p.police.x,dy=p.y-p.police.y,d=Math.hypot(dx,dy);if(d>24){p.police.x+=dx/d*Math.min(72,d);p.police.y+=dy/d*Math.min(72,d);}else{p.wanted=0;p.police=null;p.cash=Math.max(0,p.cash-100);p.x=1775;p.y=580;io.to(id).emit('relocate',{x:p.x,y:p.y});io.to(id).emit('notice',{text:'Você foi abordado. Multa de R$ 100. A ocorrência foi encerrada perto da clínica.',type:'danger'});}}else p.police=null;if(p.wanted&&Date.now()>p.heat){p.wanted--;p.heat=Date.now()+25000;}if(tick%3===0){io.to(id).emit('me',p);saved.players[p.token]={...p,id:undefined,token:undefined}}}if(tick%12===0){for(const n of chars){n.needs.food=clamp(n.needs.food-1,0,100);n.needs.energy=clamp(n.needs.energy-.5,0,100);n.needs.social=clamp(n.needs.social-.5,0,100);if(n.needs.food<35){n.needs.food=90;n.mood='Fazendo uma pausa';}n.x=n.home[0]+Math.sin(tick/25+chars.indexOf(n))*32;n.y=n.home[1]+Math.cos(tick/30+chars.indexOf(n))*18;}}},1000);
